uniform float amzp_popPunch;
uniform float amzp_popClarity;
uniform float amzp_printContrast;
uniform float amzp_printBleach;
uniform float amzp_printCrossProcess;
uniform float amzp_printFade;
uniform float amzp_printDensity;
uniform float amzp_matteBlacks;
uniform float amzp_matteWhites;
uniform float amzp_matteCurve;
uniform float amzp_matteGamma;
uniform float amzp_temperature;
uniform float amzp_tint;
uniform float amzp_exposure;
uniform float amzp_highlights;
uniform float amzp_shadows;
uniform float amzp_redGain;
uniform float amzp_greenGain;
uniform float amzp_blueGain;
uniform float amzp_redGamma;
uniform float amzp_greenGamma;
uniform float amzp_blueGamma;
uniform float amzp_skinProtect;
uniform float amzp_skinHueCenter;
uniform float amzp_skinHueRange;
uniform float amzp_globalMix;
    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float3 rgb2hsl(float3 c) {
        float mx = max(c.r, max(c.g, c.b));
        float mn = min(c.r, min(c.g, c.b));
        float l = (mx + mn) * 0.5;
        float d = mx - mn;
        float s = 0.0;
        float h = 0.0;
        if (d > 0.00001) {
            s = (l > 0.5) ? d / max(2.0 - mx - mn, 0.00001) : d / max(mx + mn, 0.00001);
            if (mx == c.r) { h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0); }
            else if (mx == c.g) { h = (c.b - c.r) / d + 2.0; }
            else { h = (c.r - c.g) / d + 4.0; }
            h /= 6.0;
        }
        return float3(h, s, l);
    }
    float h2r(float p, float q, float t) {
        if (t < 0.0) t += 1.0;
        if (t > 1.0) t -= 1.0;
        if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
        if (t < 0.5) return q;
        if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
        return p;
    }
    float3 hsl2rgb(float3 c) {
        if (c.y < 0.00001) return float3(c.z);
        float q = (c.z < 0.5) ? c.z * (1.0 + c.y) : c.z + c.y - c.z * c.y;
        float p = 2.0 * c.z - q;
        return float3(h2r(p,q,c.x+1.0/3.0), h2r(p,q,c.x), h2r(p,q,c.x-1.0/3.0));
    }
    float getSkinMask(float3 rgb) {
        if (amzp_skinProtect < 0.00001) return 0.0;
        float3 hsl = rgb2hsl(rgb);
        float hueDist = abs(hsl.x - amzp_skinHueCenter);
        hueDist = min(hueDist, 1.0 - hueDist);
        float mask = smoothstep(amzp_skinHueRange, amzp_skinHueRange * 0.3, hueDist);
        mask *= smoothstep(0.15, 0.35, hsl.y);
        mask *= smoothstep(0.1, 0.3, hsl.z) * (1.0 - smoothstep(0.8, 0.95, hsl.z));
        return mask * amzp_skinProtect;
    }
    float3 blendWash(float3 base, float3 wash, float mode) {
        if (mode < 1.5) {
            return wash;
        }
        if (mode < 2.5) {
            return base * wash;
        }
        if (mode < 3.5) {
            return 1.0 - (1.0 - base) * (1.0 - wash);
        }
        if (mode < 4.5) {
            float3 r;
            r.r = (base.r < 0.5) ? 2.0*base.r*wash.r : 1.0-2.0*(1.0-base.r)*(1.0-wash.r);
            r.g = (base.g < 0.5) ? 2.0*base.g*wash.g : 1.0-2.0*(1.0-base.g)*(1.0-wash.g);
            r.b = (base.b < 0.5) ? 2.0*base.b*wash.b : 1.0-2.0*(1.0-base.b)*(1.0-wash.b);
            return r;
        }
        if (mode < 5.5) {
            float3 r;
            r.r = (wash.r<0.5) ? 2.0*base.r*wash.r+base.r*base.r*(1.0-2.0*wash.r) : 2.0*base.r*(1.0-wash.r)+sqrt(max(base.r,0.0))*(2.0*wash.r-1.0);
            r.g = (wash.g<0.5) ? 2.0*base.g*wash.g+base.g*base.g*(1.0-2.0*wash.g) : 2.0*base.g*(1.0-wash.g)+sqrt(max(base.g,0.0))*(2.0*wash.g-1.0);
            r.b = (wash.b<0.5) ? 2.0*base.b*wash.b+base.b*base.b*(1.0-2.0*wash.b) : 2.0*base.b*(1.0-wash.b)+sqrt(max(base.b,0.0))*(2.0*wash.b-1.0);
            return r;
        }
        float3 washHSL = rgb2hsl(wash);
        float3 baseHSL = rgb2hsl(base);
        return hsl2rgb(float3(washHSL.x, washHSL.y, baseHSL.z));
    }
    float3 applyColorWash(float3 rgb) {
        if (amzp_washStrength < 0.00001) return rgb;
        float baseLum = lum(rgb);
        float3 washed = blendWash(rgb, amzp_washColor.rgb, float(int(amzp_washBlendMode)));
        washed = mix(rgb, washed, amzp_washStrength);
        if (amzp_washPreserveLum > 0.00001) {
            float washedLum = lum(washed);
            if (washedLum > 0.00001) {
                washed *= mix(1.0, baseLum / washedLum, amzp_washPreserveLum);
            }
        }
        return washed;
    }
    float3 applyZoneColors(float3 rgb) {
        float l = lum(rgb);
        if (amzp_shadowColorStr > 0.00001) {
            float shMask = 1.0 - smoothstep(amzp_shadowThreshold - amzp_shadowSoftness, amzp_shadowThreshold + amzp_shadowSoftness, l);
            shMask *= shMask;
            float3 shTinted = mix(rgb, rgb * amzp_shadowColor.rgb, amzp_shadowColorStr);
            float origLum = lum(rgb);
            float tintLum = lum(shTinted);
            if (tintLum > 0.00001) {
                shTinted *= origLum / tintLum;
            }
            rgb = mix(rgb, shTinted, shMask);
        }
        if (amzp_midtoneColorStr > 0.00001) {
            float midMask = 1.0 - abs(l - 0.5) / max(amzp_midtoneRange, 0.00001);
            midMask = clamp(midMask, 0.0, 1.0);
            midMask *= midMask;
            float3 midTinted = mix(rgb, rgb * amzp_midtoneColor.rgb, amzp_midtoneColorStr);
            float origLum = lum(rgb);
            float tintLum = lum(midTinted);
            if (tintLum > 0.00001) {
                midTinted *= origLum / tintLum;
            }
            rgb = mix(rgb, midTinted, midMask);
        }
        if (amzp_highlightColorStr > 0.00001) {
            float hlMask = smoothstep(amzp_highlightThreshold - amzp_highlightSoftness, amzp_highlightThreshold + amzp_highlightSoftness, l);
            hlMask *= hlMask;
            float3 hlTinted = mix(rgb, rgb * amzp_highlightColor.rgb, amzp_highlightColorStr);
            float origLum = lum(rgb);
            float tintLum = lum(hlTinted);
            if (tintLum > 0.00001) {
                hlTinted *= origLum / tintLum;
            }
            rgb = mix(rgb, hlTinted, hlMask);
        }
        return rgb;
    }
    float3 applyPop(float3 rgb) {
        if (abs(amzp_popContrast) > 0.5) {
            float c = amzp_popContrast / 100.0;
            float factor = 1.0 + c;
            rgb = (rgb - 0.18) * factor + 0.18;
            if (c > 0.0) {
                float s = c * 0.3;
                rgb = rgb + s * (rgb - 0.5) * (1.0 - abs(rgb - 0.5) * 2.0);
            }
        }
        if (abs(amzp_popSaturation) > 0.5) {
            float s = 1.0 + amzp_popSaturation / 100.0;
            float l = lum(rgb);
            rgb = mix(float3(l), rgb, s);
        }
        if (abs(amzp_popVibrance) > 0.5) {
            float v = amzp_popVibrance / 100.0;
            float l = lum(rgb);
            float sat = length(rgb - float3(l));
            float weight = 1.0 - clamp(sat * 3.0, 0.0, 1.0);
            rgb = mix(float3(l), rgb, 1.0 + v * weight);
        }
        if (amzp_popPunch > 0.5) {
            float p = amzp_popPunch / 100.0;
            float l = lum(rgb);
            rgb = mix(rgb, (rgb - 0.18) * (1.0 + p * 0.5) + 0.18, p);
            rgb = mix(float3(l), rgb, 1.0 + p * 0.3);
        }
        if (abs(amzp_popClarity) > 0.5) {
            float c = amzp_popClarity / 100.0;
            float l = lum(rgb);
            float midMask = 1.0 - abs(l - 0.5) * 2.0;
            midMask = max(midMask, 0.0);
            float contrast = (l - 0.5) * c * 1.5 * midMask;
            rgb += contrast;
        }
        return rgb;
    }
    float3 applyPrintFilm(float3 rgb) {
        if (abs(amzp_printContrast) > 0.5) {
            float c = amzp_printContrast / 100.0;
            float l = lum(rgb);
            float sCurve = l + c * 0.5 * (l - 0.5) * (1.0 - abs(l - 0.5) * 2.0);
            float ratio = sCurve / max(l, 0.00001);
            rgb *= ratio;
        }
        if (amzp_printBleach > 0.5) {
            float a = amzp_printBleach / 100.0;
            float l = lum(rgb);
            float3 desat = float3(l);
            float3 r;
            r.r = (l < 0.5) ? 2.0*rgb.r*desat.r : 1.0-2.0*(1.0-rgb.r)*(1.0-desat.r);
            r.g = (l < 0.5) ? 2.0*rgb.g*desat.g : 1.0-2.0*(1.0-rgb.g)*(1.0-desat.g);
            r.b = (l < 0.5) ? 2.0*rgb.b*desat.b : 1.0-2.0*(1.0-rgb.b)*(1.0-desat.b);
            rgb = mix(rgb, r, a);
        }
        if (amzp_printCrossProcess > 0.5) {
            float a = amzp_printCrossProcess / 100.0;
            float3 cp;
            cp.r = pow(max(rgb.r, 0.0), 0.8 + a * 0.3);
            cp.g = pow(max(rgb.g, 0.0), 1.0 - a * 0.15);
            cp.b = pow(max(rgb.b, 0.0), 1.2 - a * 0.1);
            cp.r += a * 0.04;
            cp.b -= a * 0.02;
            rgb = mix(rgb, cp, a);
        }
        if (amzp_printFade > 0.5) {
            float f = amzp_printFade / 100.0;
            rgb = rgb * (1.0 - f * 0.15) + f * 0.12;
            float l = lum(rgb);
            rgb = mix(rgb, float3(l), f * 0.2);
        }
        if (abs(amzp_printDensity) > 0.5) {
            float d = amzp_printDensity / 100.0;
            rgb = pow(max(rgb, 0.0), float3(1.0 + d));
        }
        return rgb;
    }
    float3 applyMatte(float3 rgb) {
        if (amzp_matteBlacks > 0.00001) {
            rgb = rgb * (1.0 - amzp_matteBlacks) + amzp_matteBlacks;
        }
        if (amzp_matteWhites > 0.00001) {
            rgb = rgb * (1.0 - amzp_matteWhites);
        }
        if (abs(amzp_matteCurve) > 0.5) {
            float c = amzp_matteCurve / 100.0;
            rgb = rgb + c * 0.3 * (rgb - 0.5) * (1.0 - abs(rgb - 0.5) * 2.0);
        }
        if (abs(amzp_matteGamma - 1.0) > 0.00001) {
            rgb = pow(max(rgb, 0.0), float3(1.0 / max(amzp_matteGamma, 0.00001)));
        }
        return rgb;
    }
    float3 applyTemperature(float3 rgb) {
        if (abs(amzp_temperature) > 0.5) {
            float t = amzp_temperature / 100.0 * 0.08;
            rgb.r += t;
            rgb.b -= t;
            rgb.g += t * 0.15;
        }
        if (abs(amzp_tint) > 0.5) {
            float t = amzp_tint / 100.0 * 0.08;
            rgb.g += t;
            rgb.r -= t * 0.3;
            rgb.b -= t * 0.3;
        }
        return rgb;
    }
    float3 applyExposure(float3 rgb) {
        if (abs(amzp_exposure) > 0.00001) {
            rgb *= pow(2.0, amzp_exposure);
        }
        float l = lum(rgb);
        if (abs(amzp_highlights) > 0.5) {
            float hlMask = smoothstep(0.5, 1.0, l);
            hlMask *= hlMask;
            float hlAdj = amzp_highlights / 100.0 * 0.4;
            float origLum = max(l, 0.00001);
            rgb *= max(l + hlAdj * hlMask, 0.0) / origLum;
        }
        if (abs(amzp_shadows) > 0.5) {
            float shMask = 1.0 - smoothstep(0.0, 0.5, l);
            shMask *= shMask;
            float shAdj = amzp_shadows / 100.0 * 0.4;
            float origLum = max(l, 0.00001);
            rgb *= max(l + shAdj * shMask, 0.0) / origLum;
        }
        return rgb;
    }
    float3 applyChannelGains(float3 rgb) {
        rgb.r *= amzp_redGain;
        rgb.g *= amzp_greenGain;
        rgb.b *= amzp_blueGain;
        if (abs(amzp_redGamma - 1.0) > 0.00001) {
            rgb.r = pow(max(rgb.r, 0.0), 1.0 / max(amzp_redGamma, 0.00001));
        }
        if (abs(amzp_greenGamma - 1.0) > 0.00001) {
            rgb.g = pow(max(rgb.g, 0.0), 1.0 / max(amzp_greenGamma, 0.00001));
        }
        if (abs(amzp_blueGamma - 1.0) > 0.00001) {
            rgb.b = pow(max(rgb.b, 0.0), 1.0 / max(amzp_blueGamma, 0.00001));
        }
        return rgb;
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float4 original = amzTexture(0, uv);
        float3 rgb = max(original.rgb, 0.0);
        float3 baseRGB = rgb;
        float skinMask = getSkinMask(rgb);
        float3 preSkin = rgb;
        rgb = applyTemperature(rgb);
        rgb = applyExposure(rgb);
        rgb = applyColorWash(rgb);
        rgb = applyZoneColors(rgb);
        rgb = applyPop(rgb);
        rgb = applyPrintFilm(rgb);
        rgb = applyMatte(rgb);
        rgb = applyChannelGains(rgb);
        if (skinMask > 0.00001) {
            float3 skinOnly = applyTemperature(preSkin);
            skinOnly = applyExposure(skinOnly);
            rgb = mix(rgb, skinOnly, skinMask);
        }
        rgb = mix(baseRGB, rgb, amzp_globalMix);
        rgb = clamp(rgb, 0.0, 1.0);
        amzOutput = float4(rgb, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
